-- Phase 14 Part 1: single-use tokens for email verification and password reset.
-- Generated by prisma migrate diff, followed by a hand-written section.

-- CreateEnum
CREATE TYPE "AccountTokenPurpose" AS ENUM ('VERIFY_EMAIL', 'RESET_PASSWORD');

-- CreateTable
CREATE TABLE "account_tokens" (
    "id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "purpose" "AccountTokenPurpose" NOT NULL,
    "token_hash" TEXT NOT NULL,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,
    "used_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "account_tokens_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "account_tokens_token_hash_key" ON "account_tokens"("token_hash");

-- CreateIndex
CREATE INDEX "account_tokens_user_id_purpose_idx" ON "account_tokens"("user_id", "purpose");

-- AddForeignKey
ALTER TABLE "account_tokens" ADD CONSTRAINT "account_tokens_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- =============================================================================================
-- Hand-written below this line: token hashes are SHA-256 hex; a token lives at most a day; a
-- token is used once and nothing else about it changes. See docs/adr/0005-built-in-authentication.md.
-- =============================================================================================

ALTER TABLE "account_tokens" ADD CONSTRAINT "account_tokens_shape"
  CHECK ("token_hash" ~ '^[0-9a-f]{64}$'
         AND "expires_at" > "created_at"
         AND "expires_at" <= "created_at" + interval '1 day'
         AND ("used_at" IS NULL OR "used_at" >= "created_at"));

CREATE FUNCTION app_account_token_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."created_at" := now();
    NEW."used_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."used_at" IS NOT NULL
     OR (NEW."user_id", NEW."purpose", NEW."token_hash", NEW."expires_at", NEW."created_at")
        IS DISTINCT FROM (OLD."user_id", OLD."purpose", OLD."token_hash", OLD."expires_at", OLD."created_at") THEN
    RAISE EXCEPTION 'an account token is used once and never changes' USING ERRCODE = 'check_violation';
  END IF;
  NEW."used_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "account_tokens_guard"
  BEFORE INSERT OR UPDATE ON "account_tokens"
  FOR EACH ROW EXECUTE FUNCTION app_account_token_guard();

REVOKE ALL ON "account_tokens" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "account_tokens" TO veyra_app;
